import java.util.HashSet;
import java.util.Scanner;
import java.util.Set;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Set<String> names = new HashSet<>();
        for (int i = 0; i < n; i++) {
            names.add(sc.next());
        }
        System.out.println("名单上一共 " + names.size() + " 只");
        System.out.println("一共投喂了 " + n + " 次");
        System.out.println("去过的名字里有 {k} 吗：" + names.contains("{k}"));
    }
}
